"""Explicit evidence and competing-option assessments after batch 35 research."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
def read(p): return json.loads((ROOT/p).read_text(encoding='utf8'))
def save(p,v): (ROOT/p).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
lib=read('audit/source-notes.json')
def source(key,url,loc,evidence,limitations='Primary institutional text inspected; no film or audio playback claimed.'):
    key='b35-'+key
    lib['sources'][key]=dict(url=url,locator=loc,evidence=evidence,checkedBy='Codex',checkedAt='2026-11-09',timeSensitive=False,nextReviewAt=None,limitations=limitations,topics=['Batch 35'])
    return key
