reviews={}
def review(i,srcs,premise,reasons,challenge,distinct,context='',bases=None):
    assert len(reasons)==4
    reviews[i]=dict(srcs=srcs,premise=premise,reasons=reasons,challenge=challenge,distinct=distinct,context=context,bases=bases or ['direct','exclusive-inference','exclusive-inference','exclusive-inference'])
review(2268,[watch,watch2],'The original 1933 watch brand is identifiable independently of later corporate names.',['Ingersoll is the explicit 1933 brand.','Timex is the later successor name, not the 1933 branding.','Bulova is not the brand assigned to this original release.','Elgin/Bradley entered the Disney watch arrangement later.'],'Tested Timex as the same corporate lineage: final wording asks the contemporary brand, excluding that reading.','No other active question asks the original watch brand.','1933 licensed wristwatch; brand rather than present corporate ownership.')
review(2269,[roy,proxy],'Roy\'s 2003 protest explicitly targets the then-CEO Eisner.',['The letter and company disclosure identify Eisner.','Iger is not the CEO whose resignation these letters demand.','Chapek is not the addressee or demanded resignation.','Wells had died in 1994; the letter praises his earlier partnership.'],'Rechecked that this is Roy E., the 2003 campaign, rather than Roy O. or the 1984 campaign.','#1607 asks Eisner tenure; this asks the distinct 2003 protest target.')
review(2270,[store],'The first Disney Store chain location has a specific city.',['Glendale Galleria is explicitly the first chain store.','Anaheim is not the named Galleria location.','Orlando airport had a different earlier shop; the final wording excludes that conflation.','New York is not the first chain location.'],'Challenged Orlando as an earlier off-park shop; changed wording to the retail chain before approving.','Distinct from park locations and company headquarters questions.')
review(2271,[name],'Disney changed its corporate name in 1986.',['The Walt Disney Company is the official new name.','Disney Enterprises is not the named 1986 corporate title.','Buena Vista Corporation is not the adopted name.','Walt Disney International is not the adopted name.'],'Checked corporate renaming against the simultaneous WED/Imagineering renaming; those are separate entities.','#1191 concerns WED Enterprises, not the parent company.')
review(2272,[gold],'A particular staged revue uses an awards ceremony format.',['Golden Mickeys is explicitly the awards-format revue.','Believe is the Greenaway father-daughter story, not this awards show.','Villains Tonight is not the title of the described ceremony.','Twice Charmed is the Cinderella alternate story, not this awards show.'],'Removed potentially misleading Magic-premiere language; assessed the unique format/title, not debut-day chronology.','No duplicate with stage shows on other ships or show-location facts.')
review(2273,[franco,francoplot,auditions],'Twice Charmed has a named evil fairy godfather.',['Primary participant credit gives Franco DiFortunato.','Lorenzo Bellafiore is not the credited character identity.','Vittorio Malaspina is not the named fairy godfather.','Carlo Bonaventura is not that character.'],'Tested alternate names as aliases: official Franco listing, full participant credit and plot account align on one name.','Distinct from the Cinderella III time reversal plot; the director confirms separate productions.')
review(2274,[toyship,toyopened],'Toy Story musical opened aboard a specific ship in 2008.',['The announcement and actual onboard event identify Wonder.','Magic is not the debut ship in either account.','Dream is not the 2008 premiere ship.','Fantasy is not the 2008 premiere ship.'],'Corroborated actual performance instead of using only a planned opening; no exact premiere day claimed.','#2346 is a different production, Frozen, with a different debut year despite the same ship.')
review(2275,[sophia,auditions],'Greenaway\'s daughter in Believe is named.',['Sophia addresses Greenaway as Dad in the official side.','Melody is not the daughter identified in these scenes.','Vanellope is not that named child.','Penny is not that named child.'],'Checked speaker labels and parent-child exchange rather than inferring a daughter from a generic synopsis.','The girl\'s name is distinct from ship listings or the identity of the show.')
review(2276,[beast],'The 2017 new production debuted on a named ship.',['The November 2017 Disney account identifies Dream.','Fantasy is not the ship in the historical debut account.','Wish is not the named 2017 ship.','Magic is not the named 2017 ship.'],'Excluded current or future show transfers by asking only the historical debut.','Atrium statue and maiden-voyage questions do not establish this later show debut.')
review(2277,[aladdin],'The official current list pairs Wish with Fantasy.',['Fantasy is the other listed ship.','Dream is absent from the complete Ship Locations list.','Magic is absent from that complete list.','Wonder is absent from that complete list.'],'Read the complete official list, with a dated stem and a scheduled recheck for transfers.','Minnie atrium statue location does not establish the Aladdin assignment.',bases=['direct','exhaustive-list','exhaustive-list','exhaustive-list'])
review(2278,[adventure,adventure2],'Global Dream belonged to the Genting Dream Cruises project before the Disney acquisition.',['Genting Hong Kong is the specified parent of Dream Cruises.','Royal Caribbean is not the named parent.','Norwegian Cruise Line is not the named parent.','MSC Cruises is not the named parent.'],'Tested whether the answer should instead be Dream Cruises: final question explicitly asks its parent.','Different from Adventure homeport, opening year, original ship name or continent facts.')
review(2279,[blue,adventure2],'The original Disney hull blue has a specific nickname.',['Both specialist descriptions call it Monica Blue.','Mickey Navy is not the named shade.','Admiral\'s Blue is not the named shade.','Pixie Blue is not the named shade.'],'Removed disputed garment detail; two independent accounts agree on the color nickname.','#432 asks hull/funnel color combination, not the custom shade name.')
review(2280,[fantasy,hudsondone],'Fantasy had a specific godmother at its 2012 New York christening.',['The Disney press release names Mariah Carey.','Kristen Bell is not the person credited at this ceremony.','Idina Menzel is not the person credited.','Jennifer Hudson christened Dream in 2011, a different ship and ceremony.'],'Distinguished Fantasy from Dream and ceremony from maiden voyage.','No other question asks Fantasy\'s 2012 godmother.')
review(2281,[hudson,hudsondone,fantasy],'A former Wonder performer became Dream godmother in 2011.',['Hudson is both the former Wonder performer and Dream godmother.','Carey is Fantasy godmother at the separate 2012 event.','Beyonce is not the appointed Dream godmother.','Whitney Houston is not the appointed Dream godmother.'],'Removed unbounded career-start premise; appointment and completed christening corroborate one person.','The related Fantasy question asks a different ship\'s sponsor.')
review(2282,[wish,wishdone],'Wish collectively honored wish children at its 2022 christening.',['Make-A-Wish children are the expressly designated group.','Cast members\' children are not the group definition.','The original crew is not the designated group.','Local schoolchildren are not the group definition.'],'Some recipients could also live locally or have cast-member parents; the question asks the designated collective group, not an individual\'s other memberships.','Distinct from the celebrity sponsors of Dream/Fantasy.','The designation includes past, present and future wish recipients.')
review(2283,[newman,osc96],'The original Toy Story score/song has a named composer.',['Randy Newman is credited with the score and song.','Thomas Newman is a different Newman and not the credited composer.','Menken did not write this score or song.','Giacchino did not write this original Toy Story score/song.'],'Checked Randy versus Thomas rather than accepting a surname-only match; original film version stated.','The Monsters Inc first Oscar question asks a separate award and song-film relationship.')
review(2284,[osc96],'The 1996 Original Song competition had a unique winning film.',['Pocahontas won for Colors of the Wind.','The Lion King is not the winner of this 1996 category.','Beauty and the Beast is not the winner at this ceremony.','Aladdin is not the winner at this ceremony.'],'Read winner and nominee category, distinguishing 1995 film year from 1996 ceremony year.','Different from #706/1381 song identity/lyricist and #718 the 1993 award.')
review(2285,[newman,osc02],'Newman\'s first competitive Oscar was the Monsters Inc song.',['The Academy records Monsters, Inc. and the named song.','Toy Story 2 is not the winning song\'s film.','A Bug\'s Life is not the winning song\'s film.','Cars is not the winning song\'s film.'],'Corroborated first-win order with D23; removed year as an elimination giveaway.','Knowing who scored Toy Story does not identify this first Oscar film.')
review(2286,[newman,osc11],'The second Newman song Oscar is tied to Toy Story 3.',['The Academy lists We Belong Together under Toy Story 3.','Cars 2 is not the film in the winning entry.','Up is not that song\'s film.','Brave is not that song\'s film.'],'Checked the exact song title and second-win sequence, not another song with the same title.','Distinct from Toy Story 3 ending plot and Newman\'s first Oscar.')
review(2287,[cocomusic,cocoscene],'The named Land of the Dead contest features a specific duet.',['Miguel and Hector perform Un Poco Loco at this contest.','Remember Me has other scenes, not this duet at the contest.','Proud Corazon is the family finale, not the contest duet.','The World Es Mi Familia belongs to the party performance, not this contest.'],'Bound the scene to the Land of the Dead; removed translated-title giveaway and checked alternate performances.','#2215 asks the theme park addition, which does not establish the original film performance scene.')
